export async function handler(event, context) {
  // 1. Приймаємо дані з фронтенду
  const { question, answer } = JSON.parse(event.body)

  // 2. Тут буде виклик AI (додамо на наступному кроці)

  // 3. Тимчасова відповідь, щоб перевірити, що все працює
  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
    body: JSON.stringify({
      receivedQuestion: question,
      receivedAnswer: answer,
      message: "Backend отримав дані!"
    })
  }
}